static int is_ws(unsigned char c)
{
    if (c == ' ' || c == '\t' || c == '\n' || c == '\v' || c == '\f' || c == '\r')
        return 1;
    return 0;
}

int main(void)
{
    int ch;
    long lines = 0, words = 0, bytes = 0;
    long maxlen = 0;
    long linelen = 0;
    int in_word = 0;
    int saw_newline = 1; /* before any input we are at a line boundary */

    while ((ch = getc(stdin)) != EOF) {
        unsigned char c = (unsigned char)ch;
        bytes++;

        if (c == '\n') {
            lines++;
            if (linelen > maxlen && saw_newline)
                maxlen = linelen;
            linelen = 0;
            saw_newline = 1;
        } else {
            linelen++;
            saw_newline = 0;

            if (is_ws(c)) {
                if (in_word) {
                    words++;
                    in_word = 0;
                }
            } else {
                in_word = 1;
            }
        }
    }

    /* Last line without trailing newline still counted as a line */
    if (!saw_newline) {
        lines++;
        if (linelen > maxlen)
            maxlen = linelen;
    } else if (bytes > 0 && saw_newline) {
        /* Input ended right after newline: check the previous line length */
        /* We already captured it above via '\n' handler, but max may need updating.
           Actually the newliner already updates maxlen. If we just ended on \n,
           the last line's len was set to 0 (new start). No extra line counted because lines
           increments on each \n and the "last no-newline" block only fires when !saw_newline. */
    }

    /* The final update for maxlen: ensure the most recent incomplete line (if any) is considered */
    /* Already handled in the blocks above. However when last char was \n,
       we need to make sure the previous line's linelen was stored. */

    printf("%ld %ld %ld %ld\n", lines, words, bytes, maxlen);
    return 0;
}

