    long bytes = 0;
    long maxlen = 0;      /* length of longest line (without \n) */
    long linelen = 0;     /* current line length in progress */
    int in_word = 0;

    while ((ch = getc(stdin)) != EOF) {
        unsigned char c = (unsigned char)ch;
        bytes++;

        if (c == '\n') {
            lines++;
            if (linelen > maxlen)
                maxlen = linelen;
            linelen = 0;
        } else {
            linelen++;
            /* word tracking: new word starts when current char is not ws
               and we were previously at a word boundary */
            if (!is_ws(c)) {
                if (!in_word) {
                    words++;
                    in_word = 1;
                }
            } else {
                in_word = 0;
            }
        }

        /* Track the last partial line (no trailing \n) for maxlen */
        if (ch != EOF) {
            if (linelen > maxlen && c != '\n') {
                /* After an \n, linelen resets to 0 then increments;
                   we use a separate path below instead of here. */
            }
        }
    }

    /* A final segment not ending with \n still contributes to maxlen.
       The spec says "A last line without a trailing newline counts as a line." */
    if (bytes > 0 && linelen > maxlen)
        maxlen = linelen;

    printf("%ld %ld %ld %ld\n", lines, words, bytes, maxlen);
    return 0;
