#include <stdio.h>
#include <stdlib.h>

static int is_blank(unsigned char c)
{
    return (c == ' ' || c == '\t' || c == '\n' ||
            c == '\v' || c == '\f' || c == '\r') ? 1 : 0;
}

int main(void)
{
    int ch;
    long lines = 0, words = 0, bytes = 0;
    long maxlen = 0;
    long linelen = 0;
    enum { S_WS, S_NWS } state = S_WS;

    while ((ch = getc(stdin)) != EOF) {
        unsigned char c = (unsigned char)ch;
        bytes++;

        if (is_blank(c)) {
            state = S_WS;
            if (c == '\n') {
                lines++;
                if (linelen > maxlen)
                    maxlen = linelen;
                linelen = 0;
            }
        } else {
            if (state == S_WS) {
                words++;
                state = S_NWS;
            }
            /* \r is not whitespace for max len purposes — it's just a byte */
            linelen++;
        }
    }

    /* Final partial line: the spec says it counts as a line for maxlen */
    if (bytes > 0 && linelen > maxlen)
        maxlen = linelen;

    printf("%ld %ld %ld %ld\n", lines, words, bytes, maxlen);
    return EXIT_SUCCESS;
}

